"""Sanity checks on the seed rows in repositories/tasks.py."""

import pytest

from repositories.tasks import _TASKS

SEED_TASKS = list(_TASKS.values())


@pytest.mark.parametrize("task", SEED_TASKS, ids=lambda t: f"task-{t['id']}")
def test_seed_task_priority_in_range(task: dict) -> None:
    assert type(task["priority"]) is int
    assert 1 <= task["priority"] <= 5


@pytest.mark.parametrize("task", SEED_TASKS, ids=lambda t: f"task-{t['id']}")
def test_seed_task_title_length(task: dict) -> None:
    assert isinstance(task["title"], str)
    assert len(task["title"]) <= 200

